window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b3e4ba933aeff4e9"]={"versions": [{"id": "FIG-b3e4ba933aeff4e9", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des LIN-Timings und LIN-Schedule-Tabellen-Modells innerhalb des Templates <code>AUTOSAR_SystemTemplate</code> (Teilbereich <code>Fibex4Lin:DataTiming</code>). Das Diagramm definiert die Struktur von LIN-Frame-Triggerings, Schedule-Tabellen und relativ getakteten Datenelementen im Free-Format.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modell umfasst folgende Entitäten, Attribute und Relationen:</p>\n<ul class=\"fig-list\">\n<li><code>CoreCommunication::FrameTriggering</code>: Abstrakte Basisklasse, spezialisiert von <code>Identifiable</code>.</li>\n<li><code>LinFrameTriggering</code>: Erbt von <code>CoreCommunication::FrameTriggering</code>. Attribute:</li>\n<li><code>checksumType: LinChecksumType</code></li>\n<li><code>identifier: Int</code></li>\n</ul>\n<p class=\"fig-p\">Aggregiert über eine Komposition <code>+relativelyScheduledTiming</code> mit Kardinalität <code>0..*</code> Instanzen von <code>RelativelyScheduledTiming</code>.</p>\n<ul class=\"fig-list\">\n<li><code>LinChecksumType</code> («enumeration»): Aufzählungstyp mit den Literalen <code>classic</code> und <code>enhanced</code>.</li>\n<li><code>LinScheduleTable</code>: Spezialisiert von <code>Identifiable</code>. Attribute:</li>\n<li><code>priority: Int</code></li>\n<li><code>runMode: RunMode</code></li>\n</ul>\n<p class=\"fig-p\">Steht in gerichteter Assoziation <code>+scheduleTable</code> (Kardinalität <code>1</code>) ausgehend von <code>RelativelyScheduledTiming</code> (Kardinalität <code>*</code>).</p>\n<ul class=\"fig-list\">\n<li><code>RelativelyScheduledTiming</code>: Basisklasse für relatives LIN-Scheduling. Attribute:</li>\n<li><code>delay: Float</code></li>\n<li><code>positionInTable: Int</code></li>\n<li><code>DataTiming</code>: Erbt per Generalisierung von <code>RelativelyScheduledTiming</code>.</li>\n<li><code>FreeFormat</code>: Komponiert über eine gerichtete Komposition mit Kardinalität <code>1</code> ausgehend von <code>DataTiming</code>. Attribut:</li>\n<li><code>ByteValue: Int [1..*]</code> (Byte-Array bzw. geordnete Sequenz von Bytewerten).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne dynamische Interaktions- oder Sequenzdiagrammelemente. Das dynamische Scheduling zur Laufzeit wird deklarativ durch die Ausführung der <code>LinScheduleTable</code> beschrieben: Jedes <code>LinFrameTriggering</code> bzw. <code>DataTiming</code> im Schedule besitzt über <code>RelativelyScheduledTiming</code> eine definierte Tabellenposition (<code>positionInTable</code>) sowie ein relatives Zeitintervall (<code>delay</code>), nach dessen Ablauf der nächste Eintrag getriggert wird. <code>FreeFormat</code> überträgt dabei die vorgegebenen Bytes (<code>ByteValue</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung für LIN-Cluster-Beschreibungen in AUTOSAR:</p>\n<ul class=\"fig-list\">\n<li><code>FreeFormat</code>-Einträge erfordern mindestens einen definierten Bytewert (<code>[1..*]</code>).</li>\n<li>Die Checksummenberechnung (<code>classic</code> vs. <code>enhanced</code>) wird zwingend über das Enumeration-Literal <code>LinChecksumType</code> typisiert.</li>\n<li><code>delay</code> ist als Fließkommazahl (<code>Float</code>) für Zeiteinheiten spezifiziert; Tabellenindizes (<code>positionInTable</code>), LIN-Identifier (<code>identifier</code>) und Prioritäten (<code>priority</code>) nutzen den ganzzahligen Basistyp <code>Int</code>.</li>\n</ul>"}, {"id": "FIG-366ef992e33f237a", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des LIN-Timings und LIN-Schedule-Tabellen-Modells innerhalb des Templates <code>AUTOSAR_SystemTemplate</code> (Teilbereich <code>Fibex4Lin:DataTiming</code>). Das Diagramm definiert die Struktur von LIN-Frame-Triggerings, Schedule-Tabellen und relativ getakteten Datenelementen im Free-Format.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modell umfasst folgende Entitäten, Attribute und Relationen:</p>\n<ul class=\"fig-list\">\n<li><code>CoreCommunication::FrameTriggering</code>: Abstrakte Basisklasse, spezialisiert von <code>Identifiable</code>.</li>\n<li><code>LinFrameTriggering</code>: Erbt von <code>CoreCommunication::FrameTriggering</code>. Attribute:</li>\n<li><code>checksumType: LinChecksumType</code></li>\n<li><code>identifier: Int</code></li>\n</ul>\n<p class=\"fig-p\">Aggregiert über eine Komposition <code>+relativelyScheduledTiming</code> mit Kardinalität <code>0..*</code> Instanzen von <code>RelativelyScheduledTiming</code>.</p>\n<ul class=\"fig-list\">\n<li><code>LinChecksumType</code> («enumeration»): Aufzählungstyp mit den Literalen <code>classic</code> und <code>enhanced</code>.</li>\n<li><code>LinScheduleTable</code>: Spezialisiert von <code>Identifiable</code>. Attribute:</li>\n<li><code>priority: Int</code></li>\n<li><code>runMode: RunMode</code></li>\n</ul>\n<p class=\"fig-p\">Steht in gerichteter Assoziation <code>+scheduleTable</code> (Kardinalität <code>1</code>) ausgehend von <code>RelativelyScheduledTiming</code> (Kardinalität <code>*</code>).</p>\n<ul class=\"fig-list\">\n<li><code>RelativelyScheduledTiming</code>: Basisklasse für relatives LIN-Scheduling. Attribute:</li>\n<li><code>delay: Float</code></li>\n<li><code>positionInTable: Int</code></li>\n<li><code>DataTiming</code>: Erbt per Generalisierung von <code>RelativelyScheduledTiming</code>.</li>\n<li><code>FreeFormat</code>: Komponiert über eine gerichtete Komposition mit Kardinalität <code>1</code> ausgehend von <code>DataTiming</code>. Attribut:</li>\n<li><code>ByteValue: Int [1..*]</code> (Byte-Array bzw. geordnete Sequenz von Bytewerten).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne dynamische Interaktions- oder Sequenzdiagrammelemente. Das dynamische Scheduling zur Laufzeit wird deklarativ durch die Ausführung der <code>LinScheduleTable</code> beschrieben: Jedes <code>LinFrameTriggering</code> bzw. <code>DataTiming</code> im Schedule besitzt über <code>RelativelyScheduledTiming</code> eine definierte Tabellenposition (<code>positionInTable</code>) sowie ein relatives Zeitintervall (<code>delay</code>), nach dessen Ablauf der nächste Eintrag getriggert wird. <code>FreeFormat</code> überträgt dabei die vorgegebenen Bytes (<code>ByteValue</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung für LIN-Cluster-Beschreibungen in AUTOSAR:</p>\n<ul class=\"fig-list\">\n<li><code>FreeFormat</code>-Einträge erfordern mindestens einen definierten Bytewert (<code>[1..*]</code>).</li>\n<li>Die Checksummenberechnung (<code>classic</code> vs. <code>enhanced</code>) wird zwingend über das Enumeration-Literal <code>LinChecksumType</code> typisiert.</li>\n<li><code>delay</code> ist als Fließkommazahl (<code>Float</code>) für Zeiteinheiten spezifiziert; Tabellenindizes (<code>positionInTable</code>), LIN-Identifier (<code>identifier</code>) und Prioritäten (<code>priority</code>) nutzen den ganzzahligen Basistyp <code>Int</code>.</li>\n</ul>"}, {"id": "FIG-96de0be1a004883f", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des LIN-Timings und LIN-Schedule-Tabellen-Modells innerhalb des Templates <code>AUTOSAR_SystemTemplate</code> (Teilbereich <code>Fibex4Lin:DataTiming</code>). Das Diagramm definiert die Struktur von LIN-Frame-Triggerings, Schedule-Tabellen und relativ getakteten Datenelementen im Free-Format.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modell umfasst folgende Entitäten, Attribute und Relationen:</p>\n<ul class=\"fig-list\">\n<li><code>CoreCommunication::FrameTriggering</code>: Abstrakte Basisklasse, spezialisiert von <code>Identifiable</code>.</li>\n<li><code>LinFrameTriggering</code>: Erbt von <code>CoreCommunication::FrameTriggering</code>. Attribute:</li>\n<li><code>checksumType :LinChecksumType</code></li>\n<li><code>identifier :Integer</code></li>\n</ul>\n<p class=\"fig-p\">Aggregiert über eine Komposition <code>+relativelyScheduledTiming</code> mit Kardinalität <code>0..*</code> Instanzen von <code>RelativelyScheduledTiming</code>.</p>\n<ul class=\"fig-list\">\n<li><code>LinChecksumType</code> («enumeration»): Aufzählungstyp mit den Literalen <code>classic</code> und <code>enhanced</code>.</li>\n<li><code>LinScheduleTable</code>: Spezialisiert von <code>Identifiable</code>. Attribute:</li>\n<li><code>priority :Integer</code></li>\n<li><code>runMode :RunMode</code></li>\n</ul>\n<p class=\"fig-p\">Steht in gerichteter Assoziation <code>+scheduleTable</code> (Kardinalität <code>1</code>) ausgehend von <code>RelativelyScheduledTiming</code> (Kardinalität <code>*</code>).</p>\n<ul class=\"fig-list\">\n<li><code>RelativelyScheduledTiming</code>: Basisklasse für relatives LIN-Scheduling. Attribute:</li>\n<li><code>delay :Float</code></li>\n<li><code>positionInTable :Integer</code></li>\n<li><code>DataTiming</code>: Erbt per Generalisierung von <code>RelativelyScheduledTiming</code>.</li>\n<li><code>FreeFormat</code>: Komponiert über eine gerichtete Komposition mit Kardinalität <code>1</code> ausgehend von <code>DataTiming</code>. Attribut:</li>\n<li><code>ByteValue :Integer [1..*]</code> (geordnete Sequenz von Bytewerten).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne dynamische Interaktions- oder Sequenzdiagrammelemente. Das dynamische Scheduling zur Laufzeit wird deklarativ durch die Ausführung der <code>LinScheduleTable</code> beschrieben: Jedes <code>LinFrameTriggering</code> bzw. <code>DataTiming</code> im Schedule besitzt über <code>RelativelyScheduledTiming</code> eine definierte Tabellenposition (<code>positionInTable</code>) sowie ein relatives Zeitintervall (<code>delay</code>), nach dessen Ablauf der nächste Eintrag getriggert wird. <code>FreeFormat</code> überträgt dabei die vorgegebenen Bytes (<code>ByteValue</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung für LIN-Cluster-Beschreibungen in AUTOSAR:</p>\n<ul class=\"fig-list\">\n<li><code>FreeFormat</code>-Einträge erfordern mindestens einen definierten Bytewert (<code>[1..*]</code>).</li>\n<li>Die Checksummenberechnung (<code>classic</code> vs. <code>enhanced</code>) wird zwingend über das Enumeration-Literal <code>LinChecksumType</code> typisiert.</li>\n<li><code>delay</code> ist als Fließkommazahl (<code>Float</code>) für Zeiteinheiten spezifiziert; Tabellenindizes (<code>positionInTable</code>), LIN-Identifier (<code>identifier</code>), Prioritäten (<code>priority</code>) und Bytewerte (<code>ByteValue</code>) nutzen den ganzzahligen Datentyp <code>Integer</code>.</li>\n</ul>"}], "trans": [{"from": "FIG-b3e4ba933aeff4e9", "to": "FIG-366ef992e33f237a", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-366ef992e33f237a", "to": "FIG-96de0be1a004883f", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><code>FreeFormat</code>: Typ des Attributs <code>ByteValue</code> von <code>Int</code> zu <code>Integer</code> geändert.</li>\n<li><code>LinFrameTriggering</code>: Typ des Attributs <code>identifier</code> von <code>Int</code> zu <code>Integer</code> geändert.</li>\n<li><code>LinScheduleTable</code>: Typ des Attributs <code>priority</code> von <code>Int</code> zu <code>Integer</code> geändert.</li>\n<li><code>RelativelyScheduledTiming</code>: Typ des Attributs <code>positionInTable</code> von <code>Int</code> zu <code>Integer</code> geändert.</li>\n<li><code>FreeFormat</code>: Schreibweise des Klassennamens im Klassenkopf zu <code>FreeFomat</code> typografisch verkürzt.</li>\n</ul>"}]};
